import {gestureTrack as track} from './gesture-track.js?v=motion-v70';
import {precisionDefaults} from './precision-motion.js?v=motion-v70';
const clamp=q=>Math.max(0,Math.min(1,q));
export function sampleGesture(seconds){const keys=track.keyframes;const age=Math.max(0,Math.min(track.duration,seconds));let a=keys[0],b=keys.at(-1);for(let i=1;i<keys.length;i++)if(age<=keys[i].age){a=keys[i-1];b=keys[i];break}const q=clamp((age-a.age)/Math.max(1e-9,b.age-a.age)),out={};for(const name of ['woman','garment','arm']){const ma=a.transforms[name]||a.transforms.woman||[[1,0,0],[0,1,0]],mb=b.transforms[name]||b.transforms.woman||ma;out[name]=ma.map((row,i)=>row.map((v,j)=>v+(mb[i][j]-v)*q))}return out}
// Shared contact handles prevent independently moving hands from separating from the blouse.
const baseHandles=[{p:[365,105],region:'woman'},{p:[390,245],region:'woman'},{p:[418,475],region:'woman'},{p:[690,111],region:'garment'},{p:[690,268],region:'garment'},{p:[675,405],region:'garment'},{p:[350,405],region:'woman'},{p:[445,377],region:'arm'},{p:[535,360],region:'garment'},{p:[647,117],region:'garment'},...[ [0,0],[480,0],[960,0],[0,270],[960,270],[0,540],[480,540],[960,540]].map(p=>({p,region:p[1]===540&&p[0]===480?'woman':null}))];
const kernel=(a,b)=>Math.exp(-((a[0]-b[0])**2+(a[1]-b[1])**2)/(185**2));
function invert(matrix){const n=matrix.length,a=matrix.map((r,i)=>[...r,...Array.from({length:n},(_,j)=>+(i===j))]);for(let i=0;i<n;i++){let p=i;for(let j=i+1;j<n;j++)if(Math.abs(a[j][i])>Math.abs(a[p][i]))p=j;[a[i],a[p]]=[a[p],a[i]];const v=a[i][i];if(Math.abs(v)<1e-12)throw Error('Degenerate gesture handles');for(let k=0;k<2*n;k++)a[i][k]/=v;for(let j=0;j<n;j++)if(j!==i){const q=a[j][i];for(let k=0;k<2*n;k++)a[j][k]-=q*a[i][k]}}return a.map(r=>r.slice(n))}
const grids=new Map(),layouts=new Map();
function regionDelta(point,region,M,f){if(!region)return [0,0];const A=M[region],source=track.sourcePivots[region].map((v,i)=>v*(i?540:960)),pivot=track.artworkPivots[region].map((v,i)=>v*(i?540:960));const delta=[A[0][0]*source[0]+A[0][1]*source[1]+A[0][2]-source[0],A[1][0]*source[0]+A[1][1]*source[1]+A[1][2]-source[1]],p=[point[0]-pivot[0],point[1]-pivot[1]];const result=[A[0][0]*p[0]+A[0][1]*p[1]-p[0]+delta[0],A[1][0]*p[0]+A[1][1]*p[1]-p[1]+delta[1]],name='gesture'+region[0].toUpperCase()+region.slice(1),gain=f[name+'Gain']??1,scale=f[name+'Scale']??1,angle=(f[name+'Rotation']||0)*Math.PI/180,dx=f[name+'X']||0,dy=f[name+'Y']||0;if(gain===1&&scale===1&&angle===0&&dx===0&&dy===0)return result;const q=[p[0]+result[0]*gain,p[1]+result[1]*gain];return [scale*(Math.cos(angle)*q[0]-Math.sin(angle)*q[1])-p[0]+dx,scale*(Math.sin(angle)*q[0]+Math.cos(angle)*q[1])-p[1]+dy]}
function weights(point,handles,inverse){const k=handles.map(h=>kernel(point,h.p));return handles.map((_,j)=>k.reduce((s,v,i)=>s+v*inverse[i][j],0))}
export function gestureGrid(elapsed,input={}){const f={...precisionDefaults,...input},duration=Math.max(.1,f.gestureDuration),hold=Math.max(.1,f.villageSeamstressHold||3),age=f.gestureTiming==='fit'?clamp(elapsed/hold)*track.duration:clamp((elapsed-Math.max(0,hold-duration))/duration)*track.duration,M=sampleGesture(age),handles=baseHandles.map((h,i)=>({...h,p:i<10?[f['gesturePin'+i+'X']??h.p[0],f['gesturePin'+i+'Y']??h.p[1]]:h.p})),layoutKey=JSON.stringify(handles.map(h=>h.p)),deltas=handles.map((h,i)=>{const a=regionDelta(h.p,h.region,M,f);return i<10?a.map((v,k)=>v+(f['gesturePin'+i+(k?'DY':'DX')]||0)):a}),nx=Math.round(Math.max(8,Math.min(36,f.gestureGridX))),ny=Math.round(Math.max(6,Math.min(28,f.gestureGridY))),key=nx+':'+ny+':'+layoutKey;
 if(!layouts.has(layoutKey)){if(layouts.size>=16){layouts.clear();grids.clear()}layouts.set(layoutKey,invert(handles.map((h,i)=>handles.map((k,j)=>kernel(h.p,k.p)+(i===j?1e-8:0)))))}const inverse=layouts.get(layoutKey);
 if(!grids.has(key)){const grid=[];for(let y=0;y<=ny;y++)for(let x=0;x<=nx;x++){const p=[x*960/nx,y*540/ny];grid.push({source:p,weights:weights(p,handles,inverse)})}grids.set(key,grid)}
 const nodes=grids.get(key).map(n=>{const [x,y]=n.source,rigid=x>=f.gestureFaceLeft&&x<=f.gestureFaceRight&&y>=f.gestureFaceTop&&y<=f.gestureFaceBottom?'woman':x>=f.gestureClothLeft&&x<=f.gestureClothRight&&y>=f.gestureClothTop&&y<=f.gestureClothBottom?'garment':null,delta=rigid?regionDelta(n.source,rigid,M,f):n.weights.reduce((sum,w,i)=>sum.map((v,k)=>v+w*deltas[i][k]),[0,0]);const manual=rigid?n.weights.reduce((sum,w,i)=>sum.map((v,k)=>v+(i<10?w*(f['gesturePin'+i+(k?'DY':'DX')]||0):0)),[0,0]):[0,0];return {source:n.source,target:n.source.map((v,k)=>v+(delta[k]+manual[k])*f.gestureStrength)}});
 const grid={nodes,nx,ny};let factor=1;if(minimumMeshAreaRatio(grid)<.20){let lo=0,hi=1;for(let i=0;i<12;i++){const mid=(lo+hi)/2,test={nodes:nodes.map(n=>({source:n.source,target:n.source.map((v,k)=>v+(n.target[k]-v)*mid)})),nx,ny};if(minimumMeshAreaRatio(test)>=.20)lo=mid;else hi=mid}factor=lo;for(const n of nodes)n.target=n.source.map((v,k)=>v+(n.target[k]-v)*factor)}
 return {nodes,nx,ny,age,active:f.gestureEnabled&&f.gestureStrength>0&&(age>0||Object.keys(f).some(k=>/^gesturePin\d+D[XY]$/.test(k)&&f[k]!==0)||['Woman','Garment','Arm'].some(part=>f['gesture'+part+'X']||f['gesture'+part+'Y']||f['gesture'+part+'Rotation']||f['gesture'+part+'Scale']!==1)),requestedStrength:f.gestureStrength,appliedStrength:f.gestureStrength*factor,handles:handles.map((h,i)=>({source:h.p,target:h.p.map((v,k)=>v+deltas[i][k]*f.gestureStrength*factor),region:h.region}))};
}
export function minimumMeshAreaRatio(grid){let minimum=Infinity;const area=(a,b,c)=>(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);for(let y=0;y<grid.ny;y++)for(let x=0;x<grid.nx;x++){const i=y*(grid.nx+1)+x;for(const ids of [[i,i+1,i+grid.nx+2],[i,i+grid.nx+2,i+grid.nx+1]]){const n=ids.map(i=>grid.nodes[i]);minimum=Math.min(minimum,area(...n.map(n=>n.target))/area(...n.map(n=>n.source)))}}return minimum}
